import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { RootState } from '../store/store';
import { toggleConfig } from '../store/schedulerSlice';
import { OptimizationConfig } from '../types';

interface ToggleItemProps {
  label: string;
  subtext: string;
  active: boolean;
  onToggle: () => void;
}

const ToggleItem: React.FC<ToggleItemProps> = ({
  label,
  subtext,
  active,
  onToggle
}) => (
  <div className="flex flex-col text-left">
    <div className="flex items-center space-x-2.5 cursor-pointer" onClick={onToggle}>
      <div
        className={`w-9 h-5 flex items-center rounded-full p-0.5 transition-colors duration-200 ${
          active ? 'bg-blue-600' : 'bg-slate-700'
        }`}
      >
        <div
          className={`bg-white w-4 h-4 rounded-full shadow-md transform transition-transform duration-200 ${
            active ? 'translate-x-4' : 'translate-x-0'
          }`}
        />
      </div>
      <span className="text-xs font-semibold text-slate-200">{label}</span>
    </div>
    <span className="text-[11px] text-slate-400 mt-1 max-w-[240px] leading-tight">
      {subtext}
    </span>
  </div>
);

interface OptimizationControlsProps {
  onResetCounters: () => void;
}

export const OptimizationControls: React.FC<OptimizationControlsProps> = ({
  onResetCounters
}) => {
  const dispatch = useDispatch();
  const config = useSelector((state: RootState) => state.scheduler.config);

  const handleToggle = (key: keyof OptimizationConfig) => {
    dispatch(toggleConfig(key));
  };

  return (
    <section className="bg-[#0b1329] border border-[#1e293b] rounded-xl p-5 mb-5 shadow-lg">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-4 pb-4 border-b border-slate-800/80">
        <ToggleItem
          label="React.memo on cards"
          subtext="Skip a card's re-render when its own props haven't changed."
          active={config.useMemoCards}
          onToggle={() => handleToggle('useMemoCards')}
        />
        <ToggleItem
          label="useCallback for handlers"
          subtext="Keep drag handlers referentially stable so memo isn't fooled."
          active={config.useCallbackHandlers}
          onToggle={() => handleToggle('useCallbackHandlers')}
        />
        <ToggleItem
          label="useMemo for agenda filter"
          subtext="Cache the filtered list; recompute only when events or day change."
          active={config.useMemoFilter}
          onToggle={() => handleToggle('useMemoFilter')}
        />
      </div>

      <div className="flex items-center justify-between">
        <ToggleItem
          label="Live clock"
          subtext="Ticks every 450ms to simulate unrelated state elsewhere in the app."
          active={config.liveClock}
          onToggle={() => handleToggle('liveClock')}
        />
        <button
          onClick={onResetCounters}
          className="px-4 py-1.5 bg-[#172033] hover:bg-[#1e2942] border border-slate-700 text-slate-300 text-xs font-medium rounded-lg transition-colors shadow-sm"
        >
          Reset counters
        </button>
      </div>
    </section>
  );
};
